public(package) macro fun check_mul_div<$T, $U>($max: $T, $x: $T, $y: $T, $z: $T) {
    let max = $max;
    let x = $x;
    let y = $y;
    let z = $z;

    // Div by zero is tested separately
    if (z == 0) return;

    // Overflows are tested separately
    let zu = z as $U;
    if ((x as $U) * (y as $U) >= ((max as $U) + 1) * zu) return;

    // Test for commutativity
    assert_eq!(x.mul_div(y, z), y.mul_div(x, z));

    // Test for precision: (x/z)*y loses floor(x%z * y / z)
    if ((x as $U) % zu * (y as $U) >= zu) {
        assert!((x / z) * y < x.mul_div(y, z));
    } else {
        assert_eq!((x / z) * y, x.mul_div(y, z));
    };
    // Test for precision: x*(y/z) loses floor(x * y%z / z)
    if ((y as $U) % zu * (x as $U) >= zu) {
        assert!(x * (y / z) < x.mul_div(y, z));
    } else {
        assert_eq!(x * (y / z), x.mul_div(y, z));
    };
}

public(package) macro fun check_mul_div_ceil<$T, $U>($max: $T, $x: $T, $y: $T, $z: $T) {
    let max = $max;
    let x = $x;
    let y = $y;
    let z = $z;

    // Div by zero is tested separately
    if (z == 0) return;

    // Overflows are tested separately
    let zu = z as $U;
    if ((x as $U) * (y as $U) > (max as $U) * zu) return;

    // Test for commutativity
    assert_eq!(x.mul_div_ceil(y, z), y.mul_div_ceil(x, z));

    // Test for precision: ceil == floor + 1 when x*y is not divisible by z
    let xyu = (x as $U) * (y as $U);
    if (xyu % zu != 0) {
        assert_eq!((x.mul_div(y, z) as $U) + 1, x.mul_div_ceil(y, z) as $U);
    } else {
        assert_eq!(x.mul_div(y, z), x.mul_div_ceil(y, z));
    };
}

public(package) macro fun test_mul_div<$T, $U>($max: $T, $cases: vector<$T>) {
    let max = $max;
    let cases = $cases;
    assert_eq!(max.mul_div(max, max.max(1)), max);
    cases!(max, cases, |case_pred, case, case_succ| {
        check_mul_div!<$T, $U>(max, case_pred, case, case_succ);
    });
    check_mul_div!<$T, $U>(max, max, max, max);
}

public(package) macro fun test_mul_div_ceil<$T, $U>($max: $T, $cases: vector<$T>) {
    let max = $max;
    let cases = $cases;
    assert_eq!(max.mul_div(max, max.max(1)), max);
    cases!(max, cases, |case_pred, case, case_succ| {
        check_mul_div_ceil!<$T, $U>(max, case_pred, case, case_succ);
    });
    check_mul_div_ceil!<$T, $U>(max, max, max, max);
}

public(package) macro fun slow_pow($base: _, $exp: u8): _ {
    let base = $base;
    let mut exp = $exp;
    let mut result = 1;
    while (exp > 0) {
        result = result * base;
        exp = exp - 1;
    };
    result
}

public(package) macro fun test_pow<$T>($max: $T, $cases: vector<$T>) {
    let max = $max;
    let cases = $cases;
    cases!(max, cases, |case_pred, case, case_succ| {
        assert_eq!(case_pred.pow(0), 1);
        assert_eq!(case_pred.pow(1), case_pred);
        assert_eq!(case.pow(0), 1);
        assert_eq!(case.pow(1), case);
        assert_eq!(case_succ.pow(0), 1);
        assert_eq!(case_succ.pow(1), case_succ);
    });
    assert_eq!((0: $T).pow(2), 0);
    assert_eq!((1: $T).pow(255), 1);
    assert_eq!((2: $T).pow(7), slow_pow!((2: $T), 7));
    assert_eq!((3: $T).pow(5), slow_pow!((3: $T), 5));
}

public(package) macro fun test_sqrt<$T>(
    $max: $T,
    $bound_cases: vector<$T>,
    $reflexive_cases: vector<$T>,
) {
    let max = $max;
    let cases = $bound_cases;
    // logical bounds cases
    let max_sqrt = max.sqrt();
    cases!(max, cases, |case_pred, case, case_succ| {
        let sqrt_pred = case_pred.sqrt();
        assert!(sqrt_pred * sqrt_pred <= case_pred);
        let sqrt = case.sqrt();
        assert!(sqrt * sqrt <= case);
        let sqrt_succ = case_succ.sqrt();
        assert!(sqrt_succ * sqrt_succ <= case_succ);

        if (sqrt_pred >= max_sqrt) return;
        assert!((sqrt_pred + 1) * (sqrt_pred + 1) > case_pred);

        if (sqrt >= max_sqrt) return;
        assert!((sqrt + 1) * (sqrt + 1) > case);

        if (sqrt_succ >= max_sqrt) return;
        assert!((sqrt_succ + 1) * (sqrt_succ + 1) > case_succ);
    });

    // simple reflexive cases
    let cases: vector<$T> = $reflexive_cases;
    cases!(max, cases, |case_pred, case, case_succ| {
        assert_eq!((case_pred * case_pred).sqrt(), case_pred);
        assert_eq!((case * case).sqrt(), case);
        assert_eq!((case_succ * case_succ).sqrt(), case_succ);
    });

    // test that the square of a non perfect square is the most recent square root perfect
    // square, rounding down
    let mut cases: vector<$T> = vector[2, 3, 4, 5, 6];
    while (!cases.is_empty()) {
        let case = cases.pop_back();
        let prev = case - 1;
        let square = case * case;
        let prev_suare = prev * prev;
        let mut i = prev_suare;
        while (i < square) {
            assert_eq!(i.sqrt(), prev);
            i = i + 1;
        }
    }
}

