#[test]
fun test_bls12381_min_pk_valid_and_invalid_sig() {
    // Test an actual Drand response.
    let pk =
        x"868f005eb8e6e4ca0a47c8a77ceaa5309a47978a7c71bc5cce96366b5d7a569937c529eeda66c7293784a9402801af31";
    let sig =
        x"a2cd8577944b84484ef557a7f92f0d5092779497cc470b1b97680b8f7c807d97250d310b801c7c2185c7c8a21032d45403b97530ca87bd8f05d0cf4ffceb4bcb9bf7184fb604967db7e9e6ea555bc51b25a9e41fbd51181f712aa73aaec749fe";
    let prev_sig =
        x"a96aace596906562dc525dba4dff734642d71b334d51324f9c9bcb5a3d6caf14b05cde91d6507bf4615cb4285e5b4efd1358ebc46b80b51e338f9dc46cca17cf2e046765ba857c04101a560887fa81aef101a5bb3b2350884558bd3adc72be37";
    let round: u64 = 2373935;
    assert!(verify_drand_round(pk, sig, prev_sig, round));
    // Check invalid signatures.
    let invalid_sig =
        x"11118577944b84484ef557a7f92f0d5092779497cc470b1b97680b8f7c807d97250d310b801c7c2185c7c8a21032d45403b97530ca87bd8f05d0cf4ffceb4bcb9bf7184fb604967db7e9e6ea555bc51b25a9e41fbd51181f712aa73aaec749fe";
    assert!(!verify_drand_round(pk, invalid_sig, prev_sig, round));
    assert!(!verify_drand_round(pk, sig, prev_sig, round + 1));
}

