module sui::vdf_tests;

use sui::vdf::{hash_to_input, vdf_verify};

#[test]
fun test_hash_to_input() {
    let seed = b"seed";
    let expected =
        x"";
    let actual = hash_to_input(&seed);
    assert!(actual == expected, 0);

    let other_seed = b"other seed";
    let actual = hash_to_input(&other_seed);
    assert!(actual != expected, 1);
}

#[test]
fun test_vdf_verify() {
    let input_seed = x"2ef29e01809053dcfc89e7acad77e13c2bf03b5a9a0bbfea555a1423f1f1ae23";
    let input_bytes = hash_to_input(&input_seed);
    let input_bytes_expected =
        x"";
    assert!(input_bytes == input_bytes_expected, 0);

    let output_bytes =
        x"";
    let proof_bytes =
        x"";
    assert!(vdf_verify(&input_bytes, &output_bytes, &proof_bytes, 100), 1);

    // Try with output from 101 iterations of the VDF instead
    let other_output_bytes =
        x"";
    let other_proof_bytes =
        x"";
    assert!(!vdf_verify(&input_bytes, &other_output_bytes, &other_proof_bytes, 100), 2);
    assert!(vdf_verify(&input_bytes, &other_output_bytes, &other_proof_bytes, 101), 3);

    // Try with valid input, output and proof but from a different group
    let input_bytes_wrong_group =
        x"";
    let output_bytes_wrong_group =
        x"";
    let proof_bytes_wrong_group =
        x"";
    assert!(
        !vdf_verify(
            &input_bytes_wrong_group,
            &output_bytes_wrong_group,
            &proof_bytes_wrong_group,
            100,
        ),
        4,
    );
}

