#[test]
fun events() {
    use sui::event;

    // calling test_scenario::end should dump events emitted during previous txes
    let sender = @0x0;
    let mut scenario = test_scenario::begin(sender);
    let e0 = E1(0);
    event::emit(e0);
    event::emit(e0);
    assert_eq!(event::num_events(), 2);

