#[defines_primitive(u128)]
module std::u128;

use std::string::String;

/// Returns the bitwise not of the value.
/// Each bit that is 1 becomes 0. Each bit that is 0 becomes 1.
public fun bitwise_not(x: u128): u128 {
    x ^ max_value!()
}

/// Return the larger of `x` and `y`
public fun max(x: u128, y: u128): u128 {
    std::macros::num_max!(x, y)
}

/// Return the smaller of `x` and `y`
public fun min(x: u128, y: u128): u128 {
    std::macros::num_min!(x, y)
}

/// Return the absolute value of x - y
public fun diff(x: u128, y: u128): u128 {
    std::macros::num_diff!(x, y)
}

/// Calculate `x * y / z`, upcasting intermediate values to avoid overflow when possible.
/// Aborts if `z` is `0`.
/// Aborts if the result is larger than `MAX`.
public fun mul_div(x: u128, y: u128, z: u128): u128 {
    std::macros::num_mul_div!<_, u256>(x, y, z)
}

/// Calculate `x * y / z`, upcasting intermediate values to avoid overflow when possible.
/// Rounds up the result if there is a remainder.
/// Aborts if `z` is `0`.
/// Aborts if the result is larger than `MAX`.
public fun mul_div_ceil(x: u128, y: u128, z: u128): u128 {
    std::macros::num_mul_div_ceil!<_, u256>(x, y, z)
}

/// Calculate x / y, but round up the result.
public fun div_ceil(x: u128, y: u128): u128 {
    std::macros::num_div_ceil!(x, y)
}

/// Return the value of a base raised to a power
public fun pow(base: u128, exponent: u8): u128 {
    std::macros::num_pow!(base, exponent)
}

/// Get a nearest lower integer Square Root for `x`. Given that this
/// function can only operate with integers, it is impossible
/// to get perfect (or precise) integer square root for some numbers.
///
/// Example:
/// ```
/// math::sqrt(9) => 3
/// math::sqrt(8) => 2 // the nearest lower square root is 4;
/// ```
///
/// In integer math, one of the possible ways to get results with more
/// precision is to use higher values or temporarily multiply the
/// value by some bigger number. Ideally if this is a square of 10 or 100.
///
/// Example:
/// ```
/// math::sqrt(8) => 2;
/// math::sqrt(8 * 10000) => 282;
/// // now we can use this value as if it was 2.82;
/// // but to get the actual result, this value needs
/// // to be divided by 100 (because sqrt(10000)).
///
///
/// math::sqrt(8 * 1000000) => 2828; // same as above, 2828 / 1000 (2.828)
/// ```
public fun sqrt(x: u128): u128 {
    std::macros::num_sqrt!<u128, u256>(x, 128)
}

/// Try to convert a `u128` to a `u8`. Returns `None` if the value is too large.
public fun try_as_u8(x: u128): Option<u8> {
    std::macros::try_as_u8!(x)
}

/// Try to convert a `u128` to a `u16`. Returns `None` if the value is too large.
public fun try_as_u16(x: u128): Option<u16> {
    std::macros::try_as_u16!(x)
}

/// Try to convert a `u128` to a `u32`. Returns `None` if the value is too large.
public fun try_as_u32(x: u128): Option<u32> {
    std::macros::try_as_u32!(x)
}

/// Try to convert a `u128` to a `u64`. Returns `None` if the value is too large.
public fun try_as_u64(x: u128): Option<u64> {
    std::macros::try_as_u64!(x)
}

public fun to_string(x: u128): String {
    std::macros::num_to_string!(x)
}

/// Try to add `x` and `y`.
/// Returns `None` if the addition would overflow.
public fun checked_add(x: u128, y: u128): Option<u128> {
    std::macros::num_checked_add!(x, y, max_value!())
}

/// Try to subtract `y` from `x`.
/// Returns `None` if `y > x`.
public fun checked_sub(x: u128, y: u128): Option<u128> {
    std::macros::num_checked_sub!(x, y)
}

/// Try to multiply `x` and `y`.
/// Returns `None` if the multiplication would overflow.
public fun checked_mul(x: u128, y: u128): Option<u128> {
    std::macros::num_checked_mul!(x, y, max_value!())
}

/// Try to divide `x` by `y`.
/// Returns `None` if `y` is zero.
public fun checked_div(x: u128, y: u128): Option<u128> {
    std::macros::num_checked_div!(x, y)
}

