    assert_eq!(option::none<u64>().fold!(0, |x| x + 1), 0);
}

#[test]
fun fold_no_drop() {
    let some = option::some(NoDrop {}).fold!(10u64, |el| {
        let NoDrop {} = el;
        100
    });
    let none = option::none<NoDrop>().fold!(10u64, |el| {
        let NoDrop {} = el;
        100
    });
    assert_eq!(some, 100);
    assert_eq!(none, 10);
}

#[test]
