module sui::object;

use std::bcs;
use sui::address;

/// Allows calling `.to_address` on an `ID` to get an `address`.
public use fun id_to_address as ID.to_address;

/// Allows calling `.to_bytes` on an `ID` to get a `vector<u8>`.
