fun read_setting_none() {
    let mut ts = ts::begin(SENDER);
    config_create(&mut WriteCap(), ts.ctx());
    ts.next_tx(SENDER);
    let id = ts::most_recent_id_shared<Config<WriteCap>>().destroy_some();
    let n = b"hello";
