        policy.confirm_request(request);

        wrapup(policy, cap, ctx);
    }

    public fun prepare(ctx: &mut TxContext): (TransferPolicy<Asset>, TransferPolicyCap<Asset>) {
        let publisher = package::test_claim(OTW {}, ctx);
